const links = phi.query("a", { limit: 500 });
const items = links.items.map(i => ({ t: (i.text||"").trim().slice(0,60), h: i.href }));
return { total: links.total, items: items.filter(i => i.h) };

const links = phi.query("a", { limit: 500 });
const items = links.items.map(i => ({ t: (i.text||"").trim().slice(0,50), h: i.href }));
const interesting = items.filter(i => /contribute|contribut|docs|help|support|guideline|release|submit|add/i.test(i.t + " " + (i.h||"")));
return { total: links.total, interesting };

const obs = phi.observe({ maxElements: 200 });
const navNodes = obs.nodes.map(n => `${n.ref}. ${n.role} "${(n.text||"").slice(0,45)}"`);
const footerLinks = phi.query("footer a, [class*=footer] a", { fields: ["href"], limit: 200 });
const uniq = {};
for (const l of footerLinks.items) { if (l.href) uniq[l.href] = (l.text||"").slice(0,60); }
return { trimmed: obs.nodes.length, total: obs.total, navNodes, footer: Object.entries(uniq).map(([h,t]) => t + " -> " + h) };

const res = phi.js(() => {
  const out = [];
  document.querySelectorAll('a').forEach(a => {
    const txt = (a.textContent||'').trim().replace(/\s+/g,' ');
    const al = a.getAttribute('aria-label') || '';
    const ti = a.getAttribute('title') || '';
    const h = a.href;
    if (/contribut|submit|submission|docs|help|support|guideline|add a release/i.test(txt + ' ' + al + ' ' + ti + ' ' + h)) {
      out.push({ txt: txt.slice(0,60), al, ti, h });
    }
  });
  const body = document.body.innerText || '';
  return { out, hasContributeInText: /contribut/i.test(body), snippet: (body.match(/[^\n]*contribut[^\n]*/gi)||[]).slice(0,10) };
});
return res;

const s5 = phi.recall("$step5");
const all = (s5 && s5.interesting) ? s5.interesting : [];
const links = phi.query("a", { fields: ["href"], limit: 500 });
const uniq = [];
const seen = new Set();
for (const l of links.items) {
  const h = l.href || "";
  if (!h || seen.has(h)) continue;
  seen.add(h);
  const txt = (l.text || "").trim();
  if (/discogs\.com\/(docs|contribute|help|support|about|guidelines)/i.test(h) || /support\.discogs/i.test(h)) uniq.push(txt + " -> " + h);
}
return { sampleFromStep5: all.length, uniq };

const nav = phi.goto("https://support.discogs.com/hc/en-us");
const obs = phi.observe({ maxElements: 120 });
const nodes = obs.nodes.map(n => `${n.ref}. ${n.role} "${(n.text||"").slice(0,50)}"`);
const links = phi.query("a", { fields: ["href"], limit: 400 });
const uniq = []; const seen = new Set();
for (const l of links.items) {
  const h = l.href || ""; const t = (l.text||"").trim().replace(/\s+/g," ");
  if (!h || seen.has(h)) continue; seen.add(h);
  if (/submi|contribut|release|add/i.test(t + " " + h)) uniq.push(t + " -> " + h);
}
return { url: nav.url, title: nav.title, total: obs.total, nodes: nodes.slice(0,40), uniq: uniq.slice(0,40) };

const url = "https://support.discogs.com/hc/en-us/articles/360004016474-Overview-Of-Submission-Guidelines-For-Releases";
const t = phi.tabs.open(url);
let tabId = t && t.tabId;
if (tabId) { try { phi.tabs.switch(tabId); } catch(e) {} }
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 15000 });
const obs = phi.observe({ maxElements: 60 });
return { opened: t, url_now: obs.url, title: obs.title, nodes: obs.nodes.map(n => `${n.ref}. ${n.role} "${(n.text||"").slice(0,60)}"`).slice(0,40), textStart: (obs.text||"").slice(0, 1500) };

const obs = phi.observe({ maxElements: 5 });
const txt = phi.text();
const h1 = phi.query("h1", { limit: 1 });
const heads = phi.query("h2, h3", { limit: 40 });
return {
  url: obs.url,
  title: obs.title,
  heading: h1.items[0] ? h1.items[0].text : null,
  sections: heads.items.map(h => h.text).filter(Boolean),
  textLen: txt.length,
  textStart: txt.slice(0, 2500)
};

const tabs = phi.tabs.list();
const obs = phi.observe({ viewportOnly: true, maxElements: 20 });
const h1 = phi.query("h1", { limit: 1 });
const lead = phi.text().slice(0, 300);
phi.keep("submission_overview", {
  page: "Overview Of Submission Guidelines For Releases",
  url: obs.url,
  title: obs.title,
  heading: h1.items[0] ? h1.items[0].text : null,
  path: "Discogs Help Center > Database & Contributing > Database Guidelines",
  keySections: ["Basic Guidelines", "Overview Of General Information", "Full Guidelines"],
  firstGuideline: lead.split("\n").slice(0, 8).join(" | ")
});
return { current: obs.url, title: obs.title, heading: h1.items[0]?.text, viewportText: (obs.text||"").slice(0,200), tabs: tabs.map(t => `${t.active ? "ACTIVE " : ""}${t.url}`) };

